mapper.select:
select a.code ,a.name ,a.path ,a.level ,a.order ,a.parentcode ,a.use_yn ,a.module ,a.view_path ,a.create_by ,a.create_dt ,a.update_by ,a.update_dt from tb_menu a where 1=1
AND a.code = #{code}
AND a.use_yn = #{useYn}
AND a.code in ( select menucode from tb_menu_auth where use_yn = 'Y' and role_id = #{role_id} )
order by a.order

mapper.insert:
insert into tb_menu(
    code
  , name
  , path
  , level
  , `order`
  , parentcode
  , use_yn
  , module
  , view_path
  , create_by
  , create_dt
)
values (
    #{code}
  , #{name}
  , #{path}
  , #{level}
  , #{order}
  , #{parentcode}
  , #{useYn}
  , #{module}
  , #{viewPath}
  , #{createBy}
  , now()
)

mapper.update:
update tb_menu
   set name = #{name}
     , path = #{path}
     , level = #{level}
     , `order` = #{order}
     , parentcode = #{parentcode}
     , use_yn = #{useYn}
     , module = #{module}
     , view_path = #{viewPath}
     , update_by = #{updateBy}
     , update_dt = now()
 where code = #{code}
